CREATE TABLE "public"."hard_gated_candidates" (
  "user_id"           uuid                     NOT NULL,
  "candidate_user_id" uuid                     NOT NULL,
  "generated_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "expires_at"        timestamp with time zone,
  "updated_at"        timestamp with time zone NOT NULL DEFAULT now(),
  "distance_km"       double precision,
  "hard_gate_version" integer                  NOT NULL DEFAULT 1,
  "consumed"          boolean                  NOT NULL DEFAULT false,
  "consumed_at"       timestamp with time zone,
  CONSTRAINT "gated_matches_check" CHECK ((user_id <> candidate_user_id)),
  CONSTRAINT "gated_matches_pkey" PRIMARY KEY (user_id, candidate_user_id)
);

CREATE TABLE "public"."interested_pair_question_answers" (
  "answer_id"           uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "user_low_id"         uuid                     NOT NULL,
  "user_high_id"        uuid                     NOT NULL,
  "question_id"         uuid                     NOT NULL,
  "asked_by_user_id"    uuid                     NOT NULL,
  "answered_by_user_id" uuid                     NOT NULL,
  "answer"              text                     NOT NULL,
  "created_at"          timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"          timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "interested_pair_question_answers_answer_not_empty" CHECK ((length(TRIM(BOTH FROM answer)) > 0)),
  CONSTRAINT "interested_pair_question_answers_different_users_check" CHECK ((asked_by_user_id <> answered_by_user_id)),
  CONSTRAINT "interested_pair_question_answers_one_answer_per_question" UNIQUE (user_low_id, user_high_id, question_id),
  CONSTRAINT "interested_pair_question_answers_pair_order_check" CHECK ((user_low_id < user_high_id)),
  CONSTRAINT "interested_pair_question_answers_pkey" PRIMARY KEY (answer_id),
  CONSTRAINT "interested_pair_question_answers_users_match_pair_check"
    CHECK (((LEAST(asked_by_user_id, answered_by_user_id) = user_low_id) AND (GREATEST(asked_by_user_id, answered_by_user_id) = user_high_id)))
);

ALTER TABLE "public"."interested_pair_question_answers"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."interested_pairs" (
  "user_low_id"                uuid                     NOT NULL,
  "user_high_id"               uuid                     NOT NULL,
  "low_questions_answered_at"  timestamp with time zone,
  "high_questions_answered_at" timestamp with time zone,
  "low_final_decision"         text,
  "high_final_decision"        text,
  "state"                      text                     NOT NULL DEFAULT 'awaiting_both_answers'::text,
  "created_at"                 timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"                 timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "interested_pairs_high_final_decision_check" CHECK (((high_final_decision IS NULL) OR (high_final_decision = ANY (ARRAY['yes'::text, 'no'::text])))),
  CONSTRAINT "interested_pairs_low_final_decision_check" CHECK (((low_final_decision IS NULL) OR (low_final_decision = ANY (ARRAY['yes'::text, 'no'::text])))),
  CONSTRAINT "interested_pairs_pkey" PRIMARY KEY (user_low_id, user_high_id),
  CONSTRAINT "interested_pairs_state_check"
    CHECK
    ((state = ANY (ARRAY['awaiting_both_answers'::text, 'awaiting_low_answers'::text, 'awaiting_high_answers'::text, 'awaiting_both_final_decisions'::text,
    'awaiting_low_final_decision'::text, 'awaiting_high_final_decision'::text, 'confirmed'::text, 'rejected'::text, 'expired'::text]))),
  CONSTRAINT "interested_pairs_user_order_check" CHECK ((user_low_id < user_high_id))
);

ALTER TABLE "public"."interested_pairs"
  ENABLE ROW LEVEL SECURITY;

