CREATE TABLE "public"."pair_state" (
  "user_low_id"     uuid                     NOT NULL,
  "user_high_id"    uuid                     NOT NULL,
  "low_seen_at"     timestamp with time zone,
  "high_seen_at"    timestamp with time zone,
  "low_decision"    text,
  "high_decision"   text,
  "low_decided_at"  timestamp with time zone,
  "high_decided_at" timestamp with time zone,
  "state"           text                     NOT NULL DEFAULT 'unseen'::text,
  "matched_at"      timestamp with time zone,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"      timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "pair_state_check1" CHECK ((user_low_id < user_high_id)),
  CONSTRAINT "pair_state_check2" CHECK ((((low_decision IS NULL) AND (low_decided_at IS NULL)) OR ((low_decision IS NOT NULL) AND (low_decided_at IS NOT NULL)))),
  CONSTRAINT "pair_state_check3" CHECK ((((high_decision IS NULL) AND (high_decided_at IS NULL)) OR ((high_decision IS NOT NULL) AND (high_decided_at IS NOT NULL)))),
  CONSTRAINT "pair_state_check4" CHECK ((((state = 'matched'::text) AND (matched_at IS NOT NULL)) OR ((state <> 'matched'::text) AND (matched_at IS NULL)))),
  CONSTRAINT "pair_state_check" CHECK ((user_low_id <> user_high_id)),
  CONSTRAINT "pair_state_high_decision_check" CHECK ((high_decision = ANY (ARRAY['like'::text, 'pass'::text, 'block'::text]))),
  CONSTRAINT "pair_state_low_decision_check" CHECK ((low_decision = ANY (ARRAY['like'::text, 'pass'::text, 'block'::text]))),
  CONSTRAINT "pair_state_pkey" PRIMARY KEY (user_low_id, user_high_id),
  CONSTRAINT "pair_state_state_check"
    CHECK ((state = ANY (ARRAY['unseen'::text, 'pending_low_like'::text, 'pending_high_like'::text, 'matched'::text, 'rejected'::text, 'blocked'::text])))
);

