CREATE OR REPLACE FUNCTION public.distance_km (
  lat1 double precision,
  lon1 double precision,
  lat2 double precision,
  lon2 double precision
)
  RETURNS double precision
  LANGUAGE sql
  IMMUTABLE
  AS $function$
    select case
        when lat1 is null or lon1 is null or lat2 is null or lon2 is null then null
        else
            6371.0 * acos(
                least(
                    1.0,
                    cos(radians(lat1)) * cos(radians(lat2)) * cos(radians(lon2) - radians(lon1))
                    + sin(radians(lat1)) * sin(radians(lat2))
                )
            )
    end
$function$;

CREATE OR REPLACE FUNCTION public.refill_gated_matches_for_user (
  p_user_id uuid,
  p_limit   integer DEFAULT 50
)
  RETURNS integer
  LANGUAGE plpgsql
  AS $function$
declare
    v_inserted_count integer := 0;
begin
    with me as (
        select
            up.user_id,
            up.date_of_birth,
            date_part('year', age(current_date, up.date_of_birth))::int as age_years,
            up.height_cm,
            up.gender_code,
            up.religion_code,
            up.relationship_intent_code,
            up.smoking_status_code,
            up.latitude,
            up.longitude,
            pref.min_age,
            pref.max_age,
            pref.min_height_cm,
            pref.max_height_cm,
            pref.max_distance_km,
            pref.exclude_smokers,
            pref.require_same_religion
        from public.user_profile up
        join public.user_preferences pref
          on pref.user_id = up.user_id
        where up.user_id = p_user_id
    ),
    candidate_pool as (
        select
            cand.user_id as candidate_user_id,
            cand.date_of_birth,
            date_part('year', age(current_date, cand.date_of_birth))::int as candidate_age_years,
            cand.height_cm,
            cand.gender_code,
            cand.religion_code,
            cand.relationship_intent_code,
            cand.smoking_status_code,
            cand.latitude,
            cand.longitude,
            cand_pref.min_age as cand_min_age,
            cand_pref.max_age as cand_max_age,
            cand_pref.min_height_cm as cand_min_height_cm,
            cand_pref.max_height_cm as cand_max_height_cm,
            cand_pref.max_distance_km as cand_max_distance_km,
            cand_pref.exclude_smokers as cand_exclude_smokers,
            cand_pref.require_same_religion as cand_require_same_religion
        from public.user_profile cand
        join public.user_preferences cand_pref
          on cand_pref.user_id = cand.user_id
        where cand.user_id <> p_user_id
    ),
    filtered_candidates as (
        select
            cp.candidate_user_id,
            public.distance_km(me.latitude, me.longitude, cp.latitude, cp.longitude) as computed_distance_km
        from candidate_pool cp
        cross join me
        where
            -- changed: only block if already present and still unconsumed
            not exists (
                select 1
                from public.hard_gated_candidates gm
                where gm.user_id = p_user_id
                  and gm.candidate_user_id = cp.candidate_user_id
                  and gm.consumed = false
            )
            and not exists (
                select 1
                from public.match_queue mq
                where mq.user_id = p_user_id
                  and mq.candidate_user_id = cp.candidate_user_id
                  and mq.status in ('queued', 'visible')
            )
            and not exists (
                select 1
                from public.matches m
                where m.user_low_id = least(p_user_id, cp.candidate_user_id)
                  and m.user_high_id = greatest(p_user_id, cp.candidate_user_id)
            )
            and not exists (
                select 1
                from public.pair_state ps
                where ps.user_low_id = least(p_user_id, cp.candidate_user_id)
                  and ps.user_high_id = greatest(p_user_id, cp.candidate_user_id)
            )
            and exists (
                select 1
                from public.user_preferred_genders my_pg
                where my_pg.user_id = p_user_id
                  and my_pg.gender_code = cp.gender_code
            )
            and exists (
                select 1
                from public.user_preferred_genders cand_pg
                where cand_pg.user_id = cp.candidate_user_id
                  and cand_pg.gender_code = me.gender_code
            )
            and cp.candidate_age_years between coalesce(me.min_age, 18) and coalesce(me.max_age, 100)
            and me.age_years between coalesce(cp.cand_min_age, 18) and coalesce(cp.cand_max_age, 100)
            and (
                me.min_height_cm is null
                or cp.height_cm is null
                or cp.height_cm >= me.min_height_cm
            )
            and (
                me.max_height_cm is null
                or cp.height_cm is null
                or cp.height_cm <= me.max_height_cm
            )
            and (
                cp.cand_min_height_cm is null
                or me.height_cm is null
                or me.height_cm >= cp.cand_min_height_cm
            )
            and (
                cp.cand_max_height_cm is null
                or me.height_cm is null
                or me.height_cm <= cp.cand_max_height_cm
            )
            and (
                me.exclude_smokers = false
                or cp.smoking_status_code is distinct from 'smoker'
            )
            and (
                cp.cand_exclude_smokers = false
                or me.smoking_status_code is distinct from 'smoker'
            )
            and (
                me.require_same_religion = false
                or (
                    me.religion_code is not null
                    and cp.religion_code is not null
                    and me.religion_code = cp.religion_code
                )
            )
            and (
                cp.cand_require_same_religion = false
                or (
                    me.religion_code is not null
                    and cp.religion_code is not null
                    and me.religion_code = cp.religion_code
                )
            )
            and (
                not exists (
                    select 1
                    from public.user_preferred_religions upr
                    where upr.user_id = p_user_id
                )
                or exists (
                    select 1
                    from public.user_preferred_religions upr
                    where upr.user_id = p_user_id
                      and upr.religion_code = cp.religion_code
                )
            )
            and (
                not exists (
                    select 1
                    from public.user_preferred_religions upr
                    where upr.user_id = cp.candidate_user_id
                )
                or exists (
                    select 1
                    from public.user_preferred_religions upr
                    where upr.user_id = cp.candidate_user_id
                      and upr.religion_code = me.religion_code
                )
            )

            -- changed: intent filter allows either direct intent match OR overlap in preference sets
            and (
                not exists (
                    select 1
                    from public.user_preferred_relationship_intents upi
                    where upi.user_id = p_user_id
                )
                or cp.relationship_intent_code is null
                or exists (
                    select 1
                    from public.user_preferred_relationship_intents upi
                    where upi.user_id = p_user_id
                      and upi.intent_code = cp.relationship_intent_code
                )
                or exists (
                    select 1
                    from public.user_preferred_relationship_intents mine
                    join public.user_preferred_relationship_intents theirs
                      on theirs.user_id = cp.candidate_user_id
                     and theirs.intent_code = mine.intent_code
                    where mine.user_id = p_user_id
                )
            )
            and (
                not exists (
                    select 1
                    from public.user_preferred_relationship_intents upi
                    where upi.user_id = cp.candidate_user_id
                )
                or me.relationship_intent_code is null
                or exists (
                    select 1
                    from public.user_preferred_relationship_intents upi
                    where upi.user_id = cp.candidate_user_id
                      and upi.intent_code = me.relationship_intent_code
                )
                or exists (
                    select 1
                    from public.user_preferred_relationship_intents mine
                    join public.user_preferred_relationship_intents theirs
                      on theirs.user_id = p_user_id
                     and theirs.intent_code = mine.intent_code
                    where mine.user_id = cp.candidate_user_id
                )
            )

            and (
                me.max_distance_km is null
                or public.distance_km(me.latitude, me.longitude, cp.latitude, cp.longitude) is null
                or public.distance_km(me.latitude, me.longitude, cp.latitude, cp.longitude) <= me.max_distance_km
            )
            and (
                cp.cand_max_distance_km is null
                or public.distance_km(me.latitude, me.longitude, cp.latitude, cp.longitude) is null
                or public.distance_km(me.latitude, me.longitude, cp.latitude, cp.longitude) <= cp.cand_max_distance_km
            )
        order by random()
        limit p_limit
    ),
    inserted as (
        insert into public.hard_gated_candidates (
            user_id,
            candidate_user_id,
            generated_at,
            distance_km,
            hard_gate_version,
            consumed
        )
        select
            p_user_id,
            fc.candidate_user_id,
            now(),
            fc.computed_distance_km,
            2,
            false
        from filtered_candidates fc
        on conflict (user_id, candidate_user_id) do nothing
        returning 1
    )
    select count(*) into v_inserted_count
    from inserted;

    return v_inserted_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_interested_pair_question_answers_updated_at()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  AS $function$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.set_interested_pairs_updated_at()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  AS $function$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.set_updated_at()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  AS $function$
begin
    new.updated_at = now();
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_user_match_questions_updated_at()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  AS $function$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$function$;

